import React, { useEffect } from 'react';
import { Routes, Route } from 'react-router-dom';
import Header from './components/Common/Header';
import Footer from './components/Common/Footer';
import PhotoWithZoom from './components/Ui/PhotoWithZoom';
import Home from './pages/home';
import AboutUs from './pages/AboutUs'

// Import our new scrolling ticker!
import TickerTape from './components/Ui/TickerTape'; 
import FinancialServices from './pages/FinancialServices';

const PageContent = ({ title }) => (
  <div>
    <h1>{title}</h1>
    <p>Welcome to the {title} page. This is a professional layout styled with deep blue and teal accents.</p>
    <h2>Gallery</h2>
    <div className="photo-grid">
      <PhotoWithZoom imageUrl="https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?q=80&w=600&auto=format&fit=crop" altText="Corporate Building" />
      <PhotoWithZoom imageUrl="https://images.unsplash.com/photo-1554224155-8d04cb21cd6c?q=80&w=600&auto=format&fit=crop" altText="Financial Charts" />
    </div>
  </div>
);

const App = () => {
  useEffect(() => {
    document.title = "mmdai.in";
  }, []);

  return (
    <div className="page-wrapper">
      <Header />

      {/* Notice we removed the sidebar logic entirely! */}
      <main className="main-layout" style={{ display: 'block' }}> 
        <div className="content-area">
          <Routes>
            <Route path="/" element={<Home />} />
            <Route path="/about-us" element={<AboutUs/>} />
            <Route path="/financial-services" element={<FinancialServices/>} />
            <Route path="/bajaj-broking" element={<Bajaj/>} />
            <Route path="/coal-transporting" element={<PageContent title="Coal Transporting" />} />
            <Route path="/accounting-services" element={<PageContent title="Accounting Services" />} />
            <Route path="/contact-us" element={<PageContent title="Contact Us" />} />
          </Routes>
        </div>
      </main>

      {/* Place the scrolling ticker below the main content, right above the footer */}
      <div style={{ maxWidth: '1200px', margin: '0 auto', width: '100%', padding: '0 20px' }}>
         <TickerTape />
      </div>

      <Footer />
    </div>
  );
};

export default App;
